"""Build an executed notebook consolidating agent visual labels."""
import nbformat as nb

b=nb.v4.new_notebook()
md,code=nb.v4.new_markdown_cell,nb.v4.new_code_cell
b.cells=[
    md('# 16.12 - Consolidate provisional visual review\n\nCombine the inspected source-train examples from 16.10, 16.11, 16.13 and 16.14 into one auditable research manifest. Preserve uncertain target states and exact source provenance. This notebook does not create a training dataset or claim clinical ground truth.'),
    code('from pathlib import Path\nimport hashlib\nimport pandas as pd\nfrom IPython.display import display\nroot=Path.cwd().resolve()\nwhile not (root / "AGENTS.md").exists():\n    if root==root.parent: raise RuntimeError("Project root not found")\n    root=root.parent\nbase=root / "data/processed/alignment_omni_frontal_candidates"\nevidence=root / "docs/reports/alignment/agent_visual_pilot"\nsource=pd.read_csv(base / "review_queue.csv",dtype={"source_image_id":str,"sha256":str}).set_index("source_image_id")\nexclude=set(pd.read_csv(root / "docs/reports/alignment/omni_frontal_candidate_audit/conservative_train_exclusions.csv",dtype=str).source_image_id)'),
    md('## 1. Keep both target statuses explicit\n\nFor earlier positive boxes, the other target remains uncertain. The later batch contains one image explicitly inspected as negative for both targets. No silent negative labels are introduced.'),
    code('first=pd.read_csv(evidence / "agent_visual_proposals.csv",dtype={"source_image_id":str})\nsecond=pd.read_csv(evidence / "active_review_states.csv",dtype={"source_image_id":str})\nthird=pd.read_csv(evidence / "heuristic_review_states.csv",dtype={"source_image_id":str})\nrecords=[]\nfor r in first.itertuples():\n    records.append({"source_image_id":r.source_image_id,"view_review":"frontal",\n        "diastema_review":"present" if r.target=="upper_midline_diastema" else "uncertain",\n        "crowding_review":"present" if r.target=="anterior_crowding" else "uncertain",\n        "reviewer":r.reviewer,"review_state":r.review_state,"visual_reason":r.visual_reason})\nrecords += second[["source_image_id","view_review","diastema_review","crowding_review","reviewer","review_state","visual_reason"]].to_dict("records")\nrecords += third[["source_image_id","view_review","diastema_review","crowding_review","reviewer","review_state","visual_reason"]].to_dict("records")\nfourth=pd.read_csv(evidence / "negative_review_states.csv",dtype={"source_image_id":str})\nrecords += fourth[["source_image_id","view_review","diastema_review","crowding_review","reviewer","review_state","visual_reason"]].to_dict("records")\nmanifest=pd.DataFrame(records)\nassert not manifest.source_image_id.duplicated().any()\nfor r in manifest.itertuples():\n    s=source.loc[r.source_image_id]\n    assert s["split"]=="train" and r.source_image_id not in exclude\n    assert hashlib.sha256((root / s["image_path"]).read_bytes()).hexdigest()==s["sha256"]\nmanifest.insert(1,"source_split","train")\nmanifest.insert(2,"source_sha256",[source.loc[id,"sha256"] for id in manifest.source_image_id])\ndisplay(manifest)'),
    md('## 2. Check target boxes against positive statuses\n\nEach present target needs at least one box. Absent and uncertain statuses must have no box of that target. Validate original-image coordinates.'),
    code('extra=pd.read_csv(evidence / "active_review_boxes.csv",dtype={"source_image_id":str})\nthird_boxes=pd.read_csv(evidence / "heuristic_review_boxes.csv",dtype={"source_image_id":str})\nboxes=pd.concat([first[["source_image_id","target","x_min","y_min","x_max","y_max","reviewer","review_state"]],extra,third_boxes],ignore_index=True)\ntargets={"upper_midline_diastema":"diastema_review","anterior_crowding":"crowding_review"}\nfor r in manifest.itertuples():\n    for target,field in targets.items():\n        count=len(boxes[(boxes.source_image_id==r.source_image_id)&(boxes.target==target)])\n        assert (count>0)==(getattr(r,field)=="present"),f"Target/box mismatch: {r.source_image_id} {target}"\nfor r in boxes.itertuples():\n    s=source.loc[r.source_image_id]\n    assert 0<=r.x_min<r.x_max<=int(s["width"]) and 0<=r.y_min<r.y_max<=int(s["height"])\nprint("Images:",len(manifest),"| Boxes:",len(boxes))\ndisplay(pd.DataFrame({field:manifest[field].value_counts() for field in ("diastema_review","crowding_review")}))'),
    md('## 3. Save the provisional snapshot\n\nThe snapshot is intentionally separate from the original OMNI annotations and approved review queue. It is a small teaching/evidence batch, not yet a valid model training split.'),
    code('for name,frame in (("agent_visual_manifest_v3.csv",manifest),("agent_visual_boxes_v3.csv",boxes)):\n    path=evidence / name\n    if path.exists(): assert pd.read_csv(path,dtype={"source_image_id":str}).equals(frame),f"Existing snapshot differs: {path}"\n    else: frame.to_csv(path,index=False)\n    print("Saved",path)\nprint("Next: more reviewed train positives and negatives, validation support, overlap resolution, rights check.")'),
]
b.metadata.kernelspec={'display_name':'DentalSelfie','language':'python','name':'dentalselfie-local'}
nb.write(b,'notebooks/alignment/16_12_agent_review_manifest.ipynb')
